        for i in range(3, int(n**0.5) + 1, 2):
            factorCount = 0
            currentSum = 1
            currentTerm = 1
            while n % i == 0:
                factorCount += 1
                n //= i
                currentTerm *= i
                currentSum += currentTerm
            res *= currentSum
        if n >= 2:
            res *= (1 + n)
    return res * 2

