def rgb_to_hsv(r, g, b):
    r /= 255.0
    g /= 255.0
    b /= 255.0

    mx = max(r, g, b)
    mn = min(r, g, b)
    df = mx - mn

    if mx == mn:
        h = 0
    elif mx == r:
        h = (60 * ((g - b) / df) + 360) % 360
    elif mx == g:
        h = (60 * ((b - r) / df) + 120) % 360
    elif mx == b:
        h = (60 * ((r - g) / df) + 240) % 360

    if mx == 0:
        s = 0
    else:
        s = (df / mx) * 100

    v = mx * 100

    return h, s, v

def mul_even_odd(list1):
    even_found = False
    odd_found = False
    product = 1

    for num in list1:
        if not even_found and num % 2 == 0:
            product *= num
            even_found = True
        elif not odd_found and num % 2 != 0:
            product *= num
            odd_found = True

        if even_found and odd_found:
            break

    return product

